uint64_t ready(const GeyserLifecycleData&data,uint64_t epoch,GeyserLifecycle&life,PoisonHoleTimers&timers,bool flush=true){CHECK(life.prepare(data,epoch,error)&&timers.prepare(data.poison(),epoch,error));const auto&hole=data.poison().holes().front();PoisonHoleClock clock;CHECK(timers.inspect(epoch,hole.id,clock,error)&&timers.advance_hole_idle(epoch,hole.id,clock.remaining+1./60.,true,error)&&life.receive_spawns(epoch,timers,error));CHECK(life.instances().size()==1);if(flush)CHECK(life.flush_additions(epoch,error));return life.instances().front();}
void drain(GeyserLifecycle&life,uint64_t epoch){std::vector<GeyserInstanceCommand>commands;CHECK(life.take_commands(epoch,commands,error));}
void methods(GeyserLifecycle&life,uint64_t epoch){std::vector<GeyserDeferredContext>contexts;for(auto id:life.instances()){GeyserInstanceSnapshot s;CHECK(life.inspect(epoch,id,s,error));if(s.pose)contexts.push_back({id,{false,false,false,false}});}GeyserNamedVoice voice=GeyserNamedVoice::Absent;CHECK(life.flush_methods(epoch,contexts,voice,error));}
